ext('c10_eng_ch5',[
C("📚","पुनरावृत्ति: मुख्य बिंदु",["वक्ता: सू की के बेटे","पुरस्कार: नोबेल शांति, 1991","विषय: लोकतंत्र, मानवाधिकार, अहिंसा","व्याकरण: पैसिव वॉइस"],"अंत में मुख्य बिंदु एक साथ दोहरा लीजिए। भाषण सू की के बेटे ने दिया। पुरस्कार नोबेल शांति पुरस्कार था, वर्ष उन्नीस सौ इक्यानवे। मुख्य विषय लोकतंत्र, मानवाधिकार और अहिंसा थे। भाषण में त्याग और साहस की भावना भी दिखी। व्याकरण में हमने पैसिव वॉइस दोहराई और नए शब्द सीखे, जैसे एक्सेप्टेंस, डेमोक्रेसी और नॉन वायलेंट। इन बिंदुओं को अपनी कॉपी के एक पन्ने पर लिखकर रखिए, ताकि परीक्षा से पहले एक नज़र में सब याद आ जाए।"),
],8)
ext('c10_eng_ch1',[
C("🏃","आधुनिक जीवन की रफ़्तार",["गाड़ी, हवाई जहाज़, मोबाइल","हर काम जल्दी में","दूरियाँ घटीं, पर सुकून घटा","इंसान मशीन की रफ़्तार से भागता"],"निबंध का विषय है आधुनिक जीवन की रफ़्तार। पहले एक शहर से दूसरे शहर पहुँचने में कई दिन लगते थे, आज हवाई जहाज़ से कुछ घंटे लगते हैं। चिट्ठी हफ़्तों में पहुँचती थी, आज संदेश एक पल में पहुँच जाता है। यह सब अच्छा है, पर इसके साथ इंसान भी मशीन की रफ़्तार से भागने लगा है। लेखक हचिंसन पूछते हैं कि इतनी तेज़ी से हम पहुँच कहाँ रहे हैं। दूरियाँ तो घटी हैं, पर सुकून घट गया है। इसी बात को वे हल्के हास्य के साथ कहते हैं।"),
C("🐢","लेखक का धीमा स्वभाव",["ख़ुद को धीमा सोचने वाला कहते हैं","बात देर से समझते हैं","इस पर हँसते हैं, दुखी नहीं","धीमापन भी एक गुण है"],"लेखक ख़ुद को धीमा सोचने वाला इंसान बताते हैं। जब तक लोग बात ख़त्म करते हैं, वे पहले वाक्य पर ही सोच रहे होते हैं। पर वे इसे कमज़ोरी मानकर रोते नहीं, बल्कि ख़ुद पर हल्का सा हँसते हैं। यही उनके लेखन का आकर्षण है। इस निबंध से हम सीखते हैं कि धीमा होना हमेशा बुरा नहीं होता। जो आदमी धीरे सोचता है, वह अक्सर गहराई से सोचता है। कछुए और ख़रगोश की कहानी याद कीजिए, जहाँ धीमा कछुआ अपनी लगन और स्थिरता से जीत जाता है।"),
C("✈️","तेज़ दोस्त की कहानी",["सुबह लंदन, दोपहर पेरिस, रात न्यूयॉर्क","कहीं ठहरकर कुछ देखा नहीं","यात्रा की गिनती, अनुभव शून्य","ज़्यादा जगह या गहरा अनुभव"],"लेखक का एक दोस्त है जो बहुत तेज़ ज़िंदगी जीता है। सुबह लंदन में, दोपहर पेरिस में और अगले दिन न्यूयॉर्क में। वह दुनिया घूम रहा है, पर क्या वह दुनिया देख रहा है? वह किसी जगह रुककर वहाँ के लोगों से बात नहीं करता और न ही कुछ गहराई से देख पाता है। उसकी यात्राओं की गिनती बहुत है, पर अनुभव कम। लेखक हमसे पूछते हैं कि क्या बहुत सारी जगहें देख लेना बेहतर है, या कम जगहें पर पूरे मन से देखना। यही सवाल पूरे निबंध का केंद्र है।"),
C("🎬","सिनेमा का दृश्य",["फ़िल्म बहुत तेज़ चलती है","लेखक पीछे रह जाते हैं","दूसरे हँसते हैं, लेखक अभी सोच में","मशीन तेज़, मन की गति धीमी"],"लेखक एक सिनेमा हॉल का उदाहरण देते हैं। फ़िल्म इतनी तेज़ी से आगे बढ़ती है कि वे पीछे रह जाते हैं। बाक़ी दर्शक किसी मज़ाक पर हँस रहे होते हैं और लेखक अभी पिछले दृश्य का अर्थ ही सोच रहे होते हैं। इस उदाहरण का आशय यह है कि मशीनें तो बहुत तेज़ हो गई हैं, पर इंसान का मन उतनी तेज़ी से नहीं चल सकता। जब हम ज़बरदस्ती इसी रफ़्तार से चलने की कोशिश करते हैं, तो थक जाते हैं और चीज़ों का आनंद नहीं ले पाते। यह हास्य के साथ एक गंभीर बात भी है।"),
C("🌿","जीवन की स्वाभाविक लय",["हर काम की अपनी गति होती है","भोजन, नींद, बातचीत जल्दबाज़ी में नहीं","प्रकृति की अपनी लय","संतुलन ही सुंदर जीवन"],"निबंध में बार-बार जीवन की स्वाभाविक लय की बात आई है, जिसे अंग्रेज़ी में रिदम कहते हैं। हर काम की अपनी एक गति होती है। भोजन आराम से चबाकर खाना चाहिए, नींद पूरी लेनी चाहिए और बातचीत बिना जल्दबाज़ी के होनी चाहिए। प्रकृति भी अपनी लय से चलती है। बीज को पेड़ बनने में समय लगता है, और फल पकने में भी। जब हम इस लय को तोड़कर हर काम में तेज़ी दिखाते हैं, तो तनाव बढ़ता है। लेखक कहते हैं कि जीवन में संतुलन होना चाहिए, यानी जहाँ ज़रूरी हो वहाँ तेज़ी और जहाँ संभव हो वहाँ धीरज।"),
C("😰","तेज़ रफ़्तार का दबाव",["तनाव और बेचैनी","परिवार के लिए समय कम","स्वास्थ्य पर बुरा असर","बच्चों पर भी बोझ"],"तेज़ रफ़्तार जीवन का सीधा असर हमारे मन और शरीर पर पड़ता है। लोग हर समय जल्दी में रहते हैं, इसलिए तनाव और बेचैनी बढ़ती है। परिवार के साथ बैठकर खाने या बात करने का समय कम हो जाता है। नींद पूरी नहीं होती और स्वास्थ्य बिगड़ता है। यहाँ तक कि बच्चे भी पढ़ाई, कोचिंग और मोबाइल की भागदौड़ में फँसे हैं। लेखक एगनी यानी पीड़ा शब्द का इस्तेमाल करते हैं, जो दिखाता है कि इस तेज़ी से इंसान कष्ट में है। इसलिए हमें कुछ समय अपने और अपनों के लिए ज़रूर निकालना चाहिए।"),
C("✍️","आर सी हचिंसन का परिचय",["ब्रिटिश उपन्यासकार और निबंधकार","हल्के व्यंग्य की शैली","आम आदमी की भाषा","जीवन के प्रति गहरी दृष्टि"],"लेखक आर सी हचिंसन ब्रिटेन के उपन्यासकार और निबंधकार थे। उनके लेखन में हल्का व्यंग्य और कोमल हास्य मिलता है। वे कठिन भाषा का प्रयोग नहीं करते, बल्कि आम आदमी की भाषा में अपनी बात कहते हैं। इस निबंध में भी उन्होंने ख़ुद पर हँसते हुए समाज की कमज़ोरी की ओर इशारा किया है। परीक्षा में लेखक का नाम, देश और निबंध की शैली के बारे में पूछा जा सकता है। इसलिए याद रखिए कि यह निबंध हास्य और व्यंग्य से भरा हुआ है और इसका विषय आधुनिक जीवन की गति है।"),
C("📝","शब्दार्थ दोहराइए",["पेस यानी गति","एगनी यानी पीड़ा","रिदम यानी लय","अनड्यू यानी अनुचित"],"नए शब्द दोहराते हैं। पेस यानी गति, एगनी यानी पीड़ा, रिदम यानी लय और अनड्यू यानी अनुचित। इनके साथ स्पीड, स्लो, हरी और रेस्ट जैसे शब्द भी याद कर लीजिए। एक अभ्यास कीजिए। हर शब्द से अपना एक अंग्रेज़ी वाक्य बनाइए। जैसे द पेस ऑफ़ लाइफ़ इज़ फ़ास्ट, यानी जीवन की गति तेज़ है। और वी नीड रिदम इन लाइफ़, यानी हमें जीवन में लय चाहिए। इन शब्दों का प्रयोग आप निबंध लिखते समय भी कर सकते हैं, जिससे आपकी भाषा समृद्ध दिखेगी।"),
C("🧩","व्याकरण: तुलना और विरोध",["बट, हाउएवर, व्हाइल","दो विरोधी बातें जोड़ना","ही इज़ फ़ास्ट, बट आई एम स्लो","जुड़ाव शब्दों का प्रयोग"],"निबंध में दो तरह के लोगों की तुलना है, तेज़ और धीमे, इसलिए जोड़ने वाले शब्द याद कर लीजिए। दो विरोधी बातों को जोड़ने के लिए बट, हाउएवर और व्हाइल का प्रयोग होता है। जैसे ही इज़ फ़ास्ट, बट आई एम स्लो, यानी वह तेज़ है पर मैं धीमा हूँ। व्हाइल ही ट्रैवल्स फ़ास्ट, आई थिंक स्लोली, यानी वह तेज़ यात्रा करता है जबकि मैं धीरे सोचता हूँ। हाउएवर सामान्यतः वाक्य के बीच या शुरू में आता है और उसके बाद कॉमा लगता है। इन तीनों शब्दों से दो-दो वाक्य बनाइए।"),
C("🏡","बिहार की जीवनशैली",["गाँव में आज भी धीमी लय","चौपाल, खेत और त्योहार","शहर की भागदौड़ से अलग","पर बदलाव आ रहा है"],"हमारे बिहार के गाँवों में आज भी जीवन की अपनी धीमी लय है। सुबह खेत की ओर जाना, दोपहर में पेड़ के नीचे आराम, शाम को चौपाल पर बैठकर बात करना। त्योहारों में पूरा परिवार इकट्ठा होता है, जैसे छठ और होली में। शहरों की भागदौड़ से यह बहुत अलग है। पर अब गाँवों में भी मोबाइल और तेज़ी आ गई है। निबंध हमें याद दिलाता है कि विकास के साथ-साथ अपनी इस मीठी लय को भी बचाकर रखना चाहिए। जो भागदौड़ में खो जाए, वह असली विकास नहीं है।"),
C("🧘","संतुलन कैसे बनाएँ",["दिन में थोड़ा समय बिना मोबाइल के","परिवार के साथ भोजन","पढ़ाई में नियमित समय","खेल और विश्राम भी ज़रूरी"],"अब सवाल है कि हम संतुलन कैसे बनाएँ। पहला, दिन में कम से कम एक घंटा बिना मोबाइल के बिताइए। दूसरा, परिवार के साथ बैठकर भोजन कीजिए और बात कीजिए। तीसरा, पढ़ाई के लिए एक नियमित समय तय कीजिए, ताकि अंतिम दिन की भागदौड़ न हो। चौथा, खेल और विश्राम को भी समय दीजिए। और पाँचवाँ, एक साथ बहुत सारे काम करने की जगह एक समय में एक काम पूरे मन से कीजिए। इससे काम की गुणवत्ता भी बढ़ती है और मन भी शांत रहता है।"),
C("📌","निबंध का सार",["आधुनिक जीवन बहुत तेज़ है","लेखक धीमे हैं, हँसकर स्वीकारते हैं","तेज़ी से तनाव और असंतुलन","संदेश: जीवन में संतुलन ज़रूरी"],"अब निबंध का सार दोहरा लें। आर सी हचिंसन इस निबंध में बताते हैं कि आधुनिक जीवन बहुत तेज़ हो गया है। वे ख़ुद धीमे सोचने वाले हैं और इसे हँसकर स्वीकार करते हैं। उनका तेज़ दोस्त दुनिया भर घूमता है, पर कुछ गहराई से देख नहीं पाता। तेज़ रफ़्तार से तनाव और असंतुलन बढ़ता है। निबंध का संदेश है कि जीवन में संतुलन चाहिए और हमें सोचने, समझने और अपनों के साथ समय बिताने की फ़ुर्सत निकालनी चाहिए।"),
C("❓","संभावित परीक्षा प्रश्न",["लेखक कौन हैं","लेखक ख़ुद को कैसा बताते हैं","तेज़ दोस्त का उदाहरण क्यों","निबंध का संदेश"],"परीक्षा के प्रश्न देखिए। पहला, लेखक कौन हैं? उत्तर, आर सी हचिंसन। दूसरा, लेखक ख़ुद को कैसा बताते हैं? उत्तर, एक धीमा सोचने वाला इंसान। तीसरा, तेज़ दोस्त का उदाहरण क्यों दिया गया है? उत्तर, यह दिखाने के लिए कि तेज़ रफ़्तार में गहरा अनुभव नहीं मिलता। चौथा, संदेश? उत्तर, जीवन में संतुलन ज़रूरी है और हमें अपनी स्वाभाविक लय नहीं खोनी चाहिए। उत्तर पूरे वाक्य में लिखिए।"),
Q("क्या आपको लगता है कि तेज़ रफ़्तार हमेशा अच्छी होती है? अपना उत्तर कारण सहित दीजिए।","नहीं, क्योंकि ज़्यादा तेज़ी से तनाव बढ़ता है और हम चीज़ों का आनंद और गहराई खो देते हैं।","एक सोचने वाला प्रश्न। क्या आपको लगता है कि तेज़ रफ़्तार हमेशा अच्छी होती है? कारण सहित सोचिए। ... उत्तर, नहीं, क्योंकि ज़्यादा तेज़ी से तनाव बढ़ता है और हम चीज़ों का आनंद और गहराई खो देते हैं। जहाँ ज़रूरी हो वहाँ तेज़ी, बाक़ी जगह धीरज।"),
],7)
